"""Harness ownership, net purchasing quantities and pin-level wire list from frozen final design."""
from pathlib import Path
import json,csv,collections
P=Path(__file__).resolve().parents[1];parts=json.loads((P/'docs/parts.json').read_text())
headers=['ID','P11','drugi_koniec','ktory_koniec_lutowany','dlugosc_mm','przewod','wtyk','kotwa_mm','wlasciciel_BOM']
rows=[['W1 PANELSAFE','J5','P04-R2.1/J8','P11',300,'7xAWG22','Mini-Fit Jr10p Au 39-01-2100; obsadzone1/2/3/4/7/9/10','10.5/14','P11'],['W2 PANELCORE','J4','P03-R2/J9','P11',300,'7xAWG22','Mini-Fit Jr8p Au 39-01-2080;6NC','10.5/14','P11'],['W3 TMOTOR HOLD','J9','P07 do potwierdzenia','P11',150,'2x2.5mm2','MSTB5p5.08; HOLD nie kupowac wtyku przed P07',12,'P11'],['W4 TSENSOR','J10','P08-R1/J4','P11',150,'2xAWG22','Mini-Fit Jr2p Au 39-01-2020',10.5,'P11'],['W5 L1 panel','J2','X2 DT04-12PB','P11',150,'2x1.5mm2 +6x0.5mm2','DEUTSCH size16 pin Au0460-202-1631','10.5/14.7','P11'],['W6 L2 panel','J3','X3 DT04-12PC','P11',150,'6x0.5mm2','DEUTSCH size16 pin Au0460-202-1631','10.5/14.7','P11'],['W7 TEST panel','J8','X8 DT04-12PA','P11',150,'2x1.5mm2 +9x0.5mm2','DEUTSCH size16 pin Au0460-202-1631','10.5/14.7','P11'],['W8 kontakty','J11','X11...X17','P11 i koncowki lutownicze kontaktow',200,'18xAWG24; max200mm kazda zyla','Koncowki zakupionych kontaktow;19/20NC','10.5/14','P11'],['W9 SCOPE','J6','X6 BNC izolowany panelowy','P11 i kubki BNC',100,'RG174 50ohm; odbiornik1Mohm','BNC izolowany od panelu',10.5,'P11'],['TAPS','J7','P05-R1/J4','P05',50,'10xAWG24 w5parach sygnal/GND','P05 W2 Mini-Fit12p Au','na P05','P05'],['ISERIES','J1','P06-R1/J3','P06',150,'2x2.5mm2','P06 W3 MSTB4p5.08 >=12A','na P06','P06']]
with (P/'docs/interfejsy.csv').open('w',newline='',encoding='utf-8-sig') as f:w=csv.writer(f,delimiter=';');w.writerow(headers);w.writerows(rows)
mapping={1:('X15',1),2:('X15',2),3:('X12',1),4:('X12',2),5:('X12',3),6:('X12',4),7:('X13',1),8:('X13',2),9:('X13',3),10:('X13',4),11:('X16',1),12:('X16',2),13:('X11',1),14:('X11',2),15:('X14',1),16:('X14',2),17:('X17',1),18:('X17',2)}
wires=[]
for row in rows:
 rid,j,mate,_,length,*_=row
 if rid.startswith(('TAPS','ISERIES')):continue
 for pin,net in parts[j]['pins'].items():
  if net=='NC':continue
  n=int(pin)
  if j=='J11':r,k=mapping[n];end=f'{r}.{k} funkcja';assert parts[r]['pins'][str(k)]==net
  elif j in ['J2','J3','J8']:end=j.replace('J','X')+'.'+pin+' komora DT'
  elif j=='J6':end='X6.CENTER' if pin=='1' else 'X6.SHELL'
  else:end=mate+'.'+pin
  wires.append([rid,j+'.'+pin,net,end,length,'lut PTH przy P11'])
with (P/'docs/lista-przewodow.csv').open('w',newline='',encoding='utf-8-sig') as f:w=csv.writer(f,delimiter=';');w.writerow(['wiazka','od','sygnal','do','mm','montaz']);w.writerows(wires)
